package org.aegis.android;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.*;
import android.os.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Actual constrained local TCP/DNS filter. Mixed per-app Tor routing is not implemented. */
public final class NetworkVpnService extends VpnService implements NativeTun.Protector {
    private static final String CHANNEL="aegis-network";private static volatile NetworkVpnService current;private static volatile String state="АЕГИС Сеть выключена";
    private final ExecutorService engine=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"aegis-tun-engine");t.setDaemon(true);return t;});private final ScheduledExecutorService guard=Executors.newSingleThreadScheduledExecutor();private volatile boolean closed=true,nativeActive;private ParcelFileDescriptor tun;private NetworkGateway gateway;private byte[] config;private Network underlying;
    static String status(){NetworkVpnService s=current;NetworkGateway g=s==null?null:s.gateway;return state+(g==null?"":"\nПередано: "+g.uploaded.get()+" байт; принято: "+g.downloaded.get()+"; отклонено потоков: "+g.denied.get());}
    static void stopLocked(Context c){c.stopService(new Intent(c,NetworkVpnService.class));}
    @Override public void onCreate(){super.onCreate();current=this;NotificationManager manager=getSystemService(NotificationManager.class);NotificationChannel channel=new NotificationChannel(CHANNEL,"АЕГИС Сеть",NotificationManager.IMPORTANCE_LOW);channel.setLockscreenVisibility(Notification.VISIBILITY_SECRET);manager.createNotificationChannel(channel);}
    @Override public int onStartCommand(Intent intent,int flags,int startId){if(!closed)return START_NOT_STICKY;if(!AndroidPolicy.CORE.equals(getPackageName())||!CoreIdentity.get(this).networkActive()){state="Сеть не запущена: нужен действующий NETWORK_CONTROL";stopSelf();return START_NOT_STICKY;}if(checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){state="Сеть не запущена: разрешите видимое уведомление службы";stopSelf();return START_NOT_STICKY;}closed=false;Intent open=new Intent(this,MainActivity.class);PendingIntent pending=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(this,CHANNEL).setSmallIcon(getResources().getIdentifier("aegis_icon","drawable",getPackageName())).setContentTitle("АЕГИС Сеть · локальная TCP-фильтрация").setContentText("Остальной UDP заблокирован; маршрутизация Tor не включена").setVisibility(Notification.VISIBILITY_SECRET).setOngoing(true).setContentIntent(pending).build();startForeground(600,notification);engine.execute(this::startEngine);guard.scheduleWithFixedDelay(()->{if(!CoreIdentity.get(this).networkActive())stopSelf();},1,10,TimeUnit.SECONDS);return START_NOT_STICKY;}
    private void startEngine(){try{ConnectivityManager cm=getSystemService(ConnectivityManager.class);Network candidate=cm.getActiveNetwork();NetworkCapabilities caps=candidate==null?null:cm.getNetworkCapabilities(candidate);if(caps==null||!caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_VPN))throw new IOException("Нужна действующая обычная сеть до включения фильтра");underlying=candidate;byte[] saved=new PrivateVault(this).get("network-domain-rules");DomainRules rules;try{rules=new DomainRules(saved==null?"":new String(saved,StandardCharsets.US_ASCII));}finally{if(saved!=null)Arrays.fill(saved,(byte)0);}gateway=new NetworkGateway(rules,this::connectProtected);String yaml="tunnel:\n  name: aegis\n  mtu: 1500\n  multi-queue: false\n  ipv4: 198.18.0.1\n  ipv6: 'fd66::1'\n  icmp: 'off'\nsocks5:\n  address: 127.0.0.1\n  port: "+gateway.port()+"\n  username: '"+gateway.user+"'\n  password: '"+gateway.password+"'\nmapdns:\n  address: 198.18.0.2\n  port: 53\n  network: 100.64.0.0\n  netmask: 255.192.0.0\n  cache-size: 4096\nmisc:\n  task-stack-size: 131072\n  tcp-buffer-size: 32768\n  max-session-count: 24\n  connect-timeout: 10000\n  tcp-read-write-timeout: 120000\n  log-level: error\n  log-file: null\n";config=yaml.getBytes(StandardCharsets.US_ASCII);if(closed)throw new IOException("Запуск отменён");Builder builder=new Builder().setSession("АЕГИС Сеть · локальная TCP-фильтрация").setMtu(1500).addAddress("198.18.0.1",32).addAddress("fd66::1",128).addRoute("0.0.0.0",0).addRoute("::",0).addDnsServer("198.18.0.2").setBlocking(false).setUnderlyingNetworks(new Network[]{underlying});tun=builder.establish();if(tun==null)throw new IOException("Системное разрешение VPN отозвано");if(closed)throw new IOException("Запуск отменён");state="Локальный TCP/DNS-фильтр запущен; нативная приёмка NOT_RUN. Tor-режим недоступен.";int result;nativeActive=true;try{if(closed)throw new IOException("Запуск отменён");result=NativeTun.run(config,tun.getFd(),rules.canonical,this);}finally{nativeActive=false;}if(!closed)throw new IOException("TUN engine завершился · код "+result);}catch(Throwable failure){if(!closed){String reason=failure.getMessage();state="Сеть остановлена: "+(reason==null?failure.getClass().getSimpleName():reason.substring(0,Math.min(240,reason.length())));}}finally{closed=true;cleanup();stopSelf();}}
    private Socket connectProtected(String host,byte[] address,int port)throws IOException {if(closed||underlying==null||!CoreIdentity.get(this).networkActive())throw new IOException("Сессия сети отозвана");InetAddress[] addresses=address==null?underlying.getAllByName(host):new InetAddress[]{InetAddress.getByAddress(address)};IOException last=new IOException("Нет разрешённого адреса назначения");for(int i=0;i<Math.min(16,addresses.length);i++){if(closed||!CoreIdentity.get(this).networkActive())throw new IOException("Сессия сети отозвана");InetAddress ip=addresses[i];if(!DomainRules.publicAddress(ip))continue;Socket socket=new Socket(java.net.Proxy.NO_PROXY);try{if(!protect(socket))throw new IOException("ОС отклонила protect(socket)");underlying.bindSocket(socket);socket.connect(new InetSocketAddress(ip,port),10000);if(closed||!CoreIdentity.get(this).networkActive())throw new IOException("Сессия отозвана");return socket;}catch(IOException e){last=e;try{socket.close();}catch(IOException ignored){}}}throw last;}
    @Override public boolean protectDescriptor(int fd){return !closed&&fd>=0&&protect(fd);}
    @Override public void onRevoke(){state="Системное разрешение VPN отозвано";stopSelf();}
    private synchronized void cleanup(){if(gateway!=null){gateway.close();gateway=null;}if(tun!=null)try{tun.close();}catch(IOException ignored){}tun=null;if(config!=null){Arrays.fill(config,(byte)0);config=null;}}
    @Override public void onDestroy(){closed=true;guard.shutdownNow();if(gateway!=null)gateway.close();if(nativeActive)try{NativeTun.quit();}catch(LinkageError ignored){}engine.shutdownNow();current=null;if(!state.startsWith("Сеть остановлена")&&!state.contains("отозвано"))state="АЕГИС Сеть выключена";stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
